import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Navigate, useNavigate } from 'react-router-dom';
import { UserIcon, MapPinIcon, PhoneIcon, EnvelopeIcon, CameraIcon } from '@heroicons/react/24/outline';
import axios from 'axios';

const Profile = () => {
  const { user, token, setUser } = useAuth();
  const navigate = useNavigate();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [profilePhoto, setProfilePhoto] = useState(null);
  const [photoPreview, setPhotoPreview] = useState(null);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (user && token) {
      loadUserProfile();
      loadUserOrders();
    }
  }, [user, token]);

  const loadUserProfile = async () => {
    try {
      const response = await axios.get('http://localhost:3000/api/users/profile', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      const userData = response.data.user;
      setUser(userData); // Update the auth context with full user data
      localStorage.setItem('farm2home_user', JSON.stringify(userData));

      // Set photo preview if user has a profile photo
      if (userData.profilePhoto) {
        setPhotoPreview(`http://localhost:3000${userData.profilePhoto}`);
      }
    } catch (error) {
      console.error('Error loading profile:', error);
    }
  };

  const loadUserOrders = () => {
    const allOrders = JSON.parse(localStorage.getItem('farm2home_orders') || '[]');
    const userOrders = allOrders.filter(order => order.customerId === user.id);
    setOrders(userOrders.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)));
    setLoading(false);
  };

  const handleLogout = () => {
    setShowLogoutModal(true);
  };

  const confirmLogout = () => {
    logout();
    navigate('/');
  };

  const cancelLogout = () => {
    setShowLogoutModal(false);
  };

  const handlePhotoChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      setProfilePhoto(file);
      const reader = new FileReader();
      reader.onload = (e) => {
        setPhotoPreview(e.target.result);
      };
      reader.readAsDataURL(file);
    }
  };

  if (!user) {
    return <Navigate to="/login" />;
  }

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-green-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading profile...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Profile Header */}
        <div className="bg-white rounded-lg shadow-sm p-6 mb-8">
          <div className="flex items-center space-x-6">
            <div className="relative">
              <div className="w-20 h-20 bg-green-600 rounded-full flex items-center justify-center overflow-hidden">
                {photoPreview ? (
                  <img 
                    src={photoPreview} 
                    alt="Profile" 
                    className="w-full h-full object-cover"
                  />
                ) : (
                  <span className="text-2xl font-bold text-white">
                    {user.name.split(' ').map(n => n[0]).join('').toUpperCase()}
                  </span>
                )}
              </div>
              <label className="absolute bottom-0 right-0 bg-blue-600 hover:bg-blue-700 text-white p-1 rounded-full cursor-pointer transition-colors duration-200">
                <CameraIcon className="w-4 h-4" />
                <input
                  type="file"
                  accept="image/*"
                  onChange={handlePhotoChange}
                  className="hidden"
                />
              </label>
            </div>
            <div className="flex-1">
              <h1 className="text-2xl font-bold text-gray-900 mb-2">
                {user.name}
              </h1>
              <div className="flex items-center space-x-4 text-sm text-gray-600">
                <div className="flex items-center">
                  <UserIcon className="w-4 h-4 mr-1" />
                  <span className="capitalize">{user.userType}</span>
                </div>
                <div className="flex items-center">
                  <EnvelopeIcon className="w-4 h-4 mr-1" />
                  <span>{user.email}</span>
                </div>
                <div className="flex items-center">
                  <PhoneIcon className="w-4 h-4 mr-1" />
                  <span>{user.phone}</span>
                </div>
              </div>
              <div className="flex items-center mt-2 text-sm text-gray-600">
                <MapPinIcon className="w-4 h-4 mr-1" />
                <span>{user.address}</span>
              </div>
            </div>
          </div>
        </div>

        {/* Stats Cards */}
        {user.userType === 'customer' && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
            <div className="bg-white p-6 rounded-lg shadow-sm">
              <p className="text-sm text-gray-600">Total Orders</p>
              <p className="text-2xl font-bold">{orders.length}</p>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-sm">
              <p className="text-sm text-gray-600">Total Spent</p>
              <p className="text-2xl font-bold">
                ₹{orders.reduce((t, o) => t + o.total, 0)}
              </p>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-sm">
              <p className="text-sm text-gray-600">Items Purchased</p>
              <p className="text-2xl font-bold">
                {orders.reduce((t, o) =>
                  t + o.items.reduce((it, i) => it + i.quantity, 0), 0
                )}
              </p>
            </div>
          </div>
        )}

        {/* Orders */}
        <div className="bg-white rounded-lg shadow-sm">
          <div className="p-6 border-b">
            <h2 className="text-xl font-semibold">
              Order History
            </h2>
          </div>

          {orders.length === 0 ? (
            <div className="text-center py-12">
              <p>No orders yet</p>
            </div>
          ) : (
            <div className="divide-y">
              {orders.map(order => (
                <div key={order.id} className="p-6">
                  <div className="flex justify-between mb-3">
                    <div>
                      <h3 className="font-semibold">
                        Order #{order.id.toString().slice(-6)}
                      </h3>
                      <p className="text-sm text-gray-600">
                        {new Date(order.createdAt).toLocaleString()}
                      </p>
                    </div>
                    <p className="font-semibold">₹{order.total}</p>
                  </div>

                  {order.items.map((item, i) => (
                    <div key={i} className="flex justify-between text-sm">
                      <p>{item.name}</p>
                      <p>{item.quantity}kg × ₹{item.price}</p>
                    </div>
                  ))}
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Account Info */}
        <div className="mt-8 bg-white p-6 rounded-lg shadow-sm">
          <h2 className="text-xl font-semibold mb-4">Account Info</h2>

          <p><b>Name:</b> {user.name}</p>
          <p><b>Email:</b> {user.email}</p>
          <p><b>Phone:</b> {user.phone}</p>
          <p><b>Address:</b> {user.address}</p>

          <button
            onClick={handleLogout}
            className="mt-6 bg-red-500 hover:bg-red-600 text-white px-6 py-2 rounded-md"
          >
            Logout
          </button>
        </div>

      </div>

      {/* 🔥 Logout Modal */}
      {showLogoutModal && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50 z-50">
          <div className="bg-white rounded-lg p-6 w-80 text-center animate-fadeIn">

            <h2 className="text-lg font-semibold mb-2">
              Confirm Logout
            </h2>

            <p className="text-sm text-gray-600 mb-6">
              Are you sure you want to logout?
            </p>

            <div className="flex justify-center space-x-4">
              <button
                onClick={cancelLogout}
                className="px-4 py-2 bg-gray-200 rounded-md"
              >
                Cancel
              </button>

              <button
                onClick={confirmLogout}
                className="px-4 py-2 bg-red-500 text-white rounded-md"
              >
                Logout
              </button>
            </div>

          </div>
        </div>
      )}

    </div>
  );
};

export default Profile;
